<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My SPS Portal</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="portal"><header><h1>My SPS Portal</h1><form method="post" action="/portal/logout"><button>Sign out</button></form></header><section class="panel"><h2>Client</h2><p><?=App\Support\View::e(trim(($client['first_name']??'').' '.($client['last_name']??'')))?></p></section><section class="panel"><h2>Services</h2><table><thead><tr><th>Service</th><th>Status</th><th>Approval</th><th>Renewal</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><?=App\Support\View::e($s['name'])?></td><td><?=App\Support\View::e($s['status'])?></td><td><?=App\Support\View::e($s['approval_level'])?></td><td><?=App\Support\View::e($s['renewal_at']??'')?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
